function policy(c,d){const p=d.business.policy,exp=p.tech.filter(x=>String(x.status).toUpperCase().includes('VENCIDO'));c.innerHTML=heading('Quiebre de política & antigüedad','Rotación Técnicos y Devoluciones Rotación son snapshots de aging; NO miden la frecuencia de consumo.')+sectionCards([card('Series fuera de política',p.expired||null,'Según tab Rotación Técnicos','⚑',terr),card('Ubicaciones auditadas',p.locations.length||null,'Técnicos y bodega','▣',forest),card('Series devolución rotación',p.returns.reduce((z,x)=>z+(x.events||1),0)||null,'Snapshot independiente de retorno','⇄'),card('Valor observado en riesgo',exp.length?exp.reduce((z,x)=>z+(Number(x.cost??x.value)||0),0):null,'Snapshot por ubicación (colones redondeados)','₡',terr,true)])+`<div class="charts">${chart('pol1','Vencidas por ubicación','Nombre del técnico y bodega','wide')}${chart('pol2','Series por material en devolución','Fuera de política, por SKU','narrow')}</div><div class="panel"><h3>Series en riesgo · técnico y ubicación</h3>${table(p.locations.sort((a,z)=>z.expired-a.expired),[['name','Ubicación'],['expired','Fuera política','num'],['within','Dentro política','num'],['amount','Valor observado','money']],80)}</div><div class="panel"><h3>Antigüedad y vencimientos</h3>${p.aggregate?table(p.tech,[['tech_name','Ubicación'],['status','Estado'],['events','Series','num'],['value','Valor aproximado','money']],80):table(p.tech.slice(0,200),[['tech_name','Ubicación'],['description','Material'],['serial','Serie'],['days','Días','num'],['status','Estado'],['cost','Valor','money']],80)}</div>`;bars('pol1',p.locations.sort((a,z)=>z.expired-a.expired),'name','expired',{left:230,top:16,color:terr});bars('pol2',p.returns.filter(x=>String(x.status).includes('VENCIDO')).sort((a,z)=>(z.events||1)-(a.events||1)).map(x=>({...x,description:(d.business.catalog.find(y=>y.sku===x.sku)?.description||x.description),events:x.events||1})),'description','events',{left:220,top:14,color:forest})}
function quality(c,d){const q=d.quality,k=d.kpis;c.innerHTML=heading('Calidad & cobertura','Identifique datos sin evidencia antes de generar conclusiones')+sectionCards([card('Consumos deduplicados',q.duplicate_consumptions,'Eventos equivalentes entre fuentes','☑'),card('SKU sin catálogo',q.unknown_sku,'Dimensión SKU ausente','⚑',terr),card('SKU sin costo',q.missing_cost,'No se valorizan en cero','₡')])+`<div class="grid2"><div class="panel"><h3>Estado de datasets</h3>${sourceStats(d)}</div><div class="panel"><h3>Trazabilidad de cortes</h3>${Object.entries(d.coverage.cuts).map(([t,v])=>`<div class="stat-row"><span>${esc(t.replaceAll('_',' ').toUpperCase())}</span><strong>${esc(v||'SIN CARGAR')}</strong></div>`).join('')}</div></div>`+heading('Explorador de registros','Paginación y búsqueda en servidor; datos saneados')+`<div class="panel"><div class="table-tools"><select id="dataType">${Object.entries(d.coverage.sources).map(([type,v])=>`<option value="${type}">${esc(type.replaceAll('_',' '))} · ${v.rows}</option>`).join('')}</select><input id="dataSearch" placeholder="Buscar en registros…"><button id="dataSearchBtn">Buscar</button><button id="rowCsv" class="btn-quiet">↓ CSV</button></div><div id="rowResults"></div><div class="pagination"><button id="rowPrev">← Anterior</button><span id="rowPage">—</span><button id="rowNext">Siguiente →</button></div></div>`;$('dataType').value=V.table.type in d.coverage.sources?V.table.type:Object.keys(d.coverage.sources)[0];$('dataType').onchange=e=>{V.table.type=e.target.value;V.table.offset=0;loadTable()};$('dataSearchBtn').onclick=()=>{V.table.q=$('dataSearch').value;V.table.offset=0;loadTable()};$('dataSearch').onkeydown=e=>{if(e.key==='Enter')$('dataSearchBtn').click()};$('rowPrev').onclick=()=>{V.table.offset=Math.max(0,V.table.offset-V.table.limit);loadTable()};$('rowNext').onclick=()=>{V.table.offset+=V.table.limit;loadTable()};$('rowCsv').onclick=()=>{window.location.href='/api/exports?type='+encodeURIComponent(V.table.type)};loadTable()}
async function loadTable(){try{const z=await api('/api/rows?'+new URLSearchParams({type:V.table.type,offset:String(V.table.offset),limit:String(V.table.limit),q:V.table.q,sort:V.table.sort,dir:V.table.dir}));if(V.table.offset>=z.total&&z.total>0){V.table.offset=0;return loadTable()}const headers=Object.keys(z.rows[0]||{}).filter(k=>!k.startsWith('_'));$('rowResults').innerHTML=table(z.rows,headers.map(k=>[k,k+(V.table.sort===k?(V.table.dir==='desc'?' ▼':' ▲'):' ↕')]),V.table.limit);$('rowResults').querySelectorAll('th').forEach((th,i)=>{th.title='Ordenar por '+headers[i];th.tabIndex=0;th.classList.add('sortable');const toggle=()=>{const col=headers[i];V.table.dir=V.table.sort===col&&V.table.dir==='asc'?'desc':'asc';V.table.sort=col;V.table.offset=0;loadTable()};th.onclick=toggle;th.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();toggle()}}});$('rowPage').textContent=`${nfmt(z.offset+Math.min(z.limit,z.total))} de ${nfmt(z.total)}`;$('rowPrev').disabled=z.offset===0;$('rowNext').disabled=z.offset+z.limit>=z.total}catch(e){toast(e.message)}}
function admin(c,d){const status=V.authenticated;c.innerHTML=heading('Administración y fuentes','Google Sheets de solo lectura · importación local de respaldo · sin cambiar producción')+`<div class="panel"><h3>Acceso administrativo</h3><p>La clave se muestra en la consola de RUN_LOCAL.cmd. No hay usuario ni clave predefinida dentro del ZIP; la aplicación escucha solo en 127.0.0.1.</p>${status?`<div class="login-grid"><span class="chip good">✓ Sesión local autorizada</span><button class="btn-quiet" id="logout">Cerrar sesión</button></div>`:`<div class="login-grid"><input type="password" id="adminKey" placeholder="Clave temporal de esta ejecución" autocomplete="off"><button class="btn-primary" id="login">Desbloquear importadores</button></div>`}</div>`+`<div class="panel" style="margin-top:15px"><div class="table-tools"><div><h3>Google Sheets · Fuente principal</h3><p>Actualización automática con cuenta de servicio y permiso de visualización. El servidor lee, procesa y guarda un snapshot local; nunca escribe en Google Sheets.</p></div><span id="sheetLiveBadge" class="chip">SIN CONFIGURAR</span></div><div class="grid2"><div><label class="gc-sync-label">ID del Google Sheets</label><input style="width:100%" id="sheetID" placeholder="ID del documento" ${status?'':'disabled'}><label class="gc-sync-label">Ruta JSON de cuenta de servicio (solo en este equipo)</label><input style="width:100%" id="sheetKeyPath" placeholder="C:\\credenciales\\greencall-readonly.json" autocomplete="off" ${status?'':'disabled'}><small>La clave privada no se copia al ZIP ni se envía al navegador. Comparta el Sheets como lector con el correo de la cuenta de servicio.</small></div><div><label class="gc-sync-label">Sincronizar cada (minutos)</label><input id="sheetInterval" type="number" min="5" max="120" value="10" ${status?'':'disabled'}><label class="gc-sync-label">Reconciliación completa cada (horas)</label><input id="sheetFull" type="number" min="1" max="168" value="24" ${status?'':'disabled'}><small>Primera vez: descarga completa. Luego: últimos 3.000 registros de Consumos y snapshot completo de las demás pestañas; conciliación total cada 24 h. Solo mientras RUN_LOCAL.cmd siga abierto.</small></div></div><div class="sync-buttons"><button class="btn-primary" id="sheetSave" ${status?'':'disabled'}>Guardar configuración</button><button id="sheetTest" class="btn-quiet" ${status?'':'disabled'}>Probar acceso</button><button id="sheetIncremental" class="btn-primary" ${status?'':'disabled'}>Sincronizar ahora</button><button id="sheetFullSync" class="btn-quiet" ${status?'':'disabled'}>Reconciliar todo</button><button id="sheetStop" class="btn-quiet" ${status?'':'disabled'}>Desactivar</button></div><div class="import-log" id="sheetProgress">Consultando estado de Google Sheets…</div><small>Si falla una pestaña, no se reemplaza parcialmente la información previa. Los históricos precargados siguen disponibles si no hay Internet.</small></div>`+`<div class="grid2" style="margin-top:15px"><div class="panel"><h3>Actualizar datos · Multiarchivo</h3><p>Excel XLSX/XLSM/CSV sin conexión a Internet. Puede copiar cualquier pestaña del Google Sheets a Excel; la fuente se identifica por sus encabezados, no por el nombre.</p><div class="dropzone" id="dropzone"><strong>⇧ Arrastre archivos aquí</strong><small>Admite múltiples archivos, columnas reordenadas y encabezados sin tildes.</small><input type="file" id="files" accept=".xlsx,.xlsm,.csv" multiple ${status?'':'disabled'}></div><div class="sap-cut"><label for="sapCutDate">Corte para <b>Cantidades SAP</b> sin fecha propia (opcional)</label><input id="sapCutDate" type="date"><small>Solo para importar Cantidades SAP. No se inventa fecha si queda vacío.</small></div><div class="login-grid" style="margin-top:10px"><button class="btn-primary" id="analyze" ${status?'':'disabled'}>Analizar / previsualizar</button><button class="btn-primary" id="apply" ${status?'':'disabled'}>Aplicar previews seleccionadas</button></div><div id="preview" class="import-log">${V.staged.length?V.staged.map(x=>`<div class="stat-row"><label><input type="checkbox" class="import-select" value="${x.id}" checked> ${esc(x.filename)}</label><span>${x.records.map(z=>esc(z.type||'No reconocido')+' ('+nfmt(z.received)+')').join(', ')}</span></div>`).join(''):'<p class="muted">No hay archivos preparados para aplicar.</p>'}</div></div><div class="panel"><h3>Fuentes actuales</h3>${sourceStats(d)}<h3 style="margin-top:20px">Planificación · umbrales configurables</h3><p>Estos valores son parámetros operativos ilustrativos, no políticas oficiales de GreenCall.</p><div class="stat-row"><span>Crítico por cobertura (días)</span><input id="critical" type="number" min="1" max="365" value="7"></div><div class="stat-row"><span>Alto (días)</span><input id="high" type="number" min="1" max="365" value="15"></div><div class="stat-row"><span>Medio (días)</span><input id="medium" type="number" min="1" max="365" value="30"></div><div class="stat-row"><span>Lead time global (opcional)</span><input id="lead" type="number" min="1" max="365" placeholder="Sin parametrizar"></div><div style="margin:12px 0"><label style="font-size:11px;font-weight:750">Aliases validados (pseudo-SKU=SKU oficial, una línea por material)</label><textarea id="aliases" rows="3" style="width:100%;resize:vertical;padding:8px;border:1px solid #eadfce;border-radius:8px" placeholder="PEND-EJEMPLO=1234567"></textarea></div><button class="btn-primary" id="saveSettings" ${status?'':'disabled'}>Guardar configuración</button><p>La compra sugerida permanece inactiva hasta confirmar lead time y stock vigente por SKU.</p></div></div>`;if(status){$('logout').onclick=async()=>{await api('/api/logout',{method:'POST'});V.authenticated=false;render()};$('files').onchange=()=>toast($('files').files.length+' archivo(s) seleccionados');const dz=$('dropzone');dz.ondragover=e=>{e.preventDefault();dz.classList.add('drag')};dz.ondragleave=()=>dz.classList.remove('drag');dz.ondrop=e=>{e.preventDefault();dz.classList.remove('drag');V.dropFiles=[...e.dataTransfer.files];toast(`${V.dropFiles.length} archivos listos para analizar`)};$('analyze').onclick=analyzeFiles;$('apply').onclick=applyFiles;$('saveSettings').onclick=async()=>{try{const b={critical_days:+$('critical').value,high_days:+$('high').value,medium_days:+$('medium').value,lead_time:$('lead').value||null,aliases:Object.fromEntries(($('aliases')?.value||'').split(/\r?\n/).map(line=>line.trim()).filter(Boolean).filter(line=>line.includes('=')).map(line=>line.split('=').map(x=>x.trim().toUpperCase())).filter(a=>a.length===2&&a[0]&&a[1]))};await api('/api/config',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(b)});toast('Parámetros locales actualizados');await refresh()}catch(e){toast(e.message)}};api('/api/config').then(s=>{if($('critical')){$('critical').value=s.critical_days;$('high').value=s.high_days;$('medium').value=s.medium_days;$('lead').value=s.lead_time??'';if($('aliases'))$('aliases').value=Object.entries(s.aliases||{}).map(([k,v])=>k+'='+v).join('\n')}})}else $('login').onclick=async()=>{try{await api('/api/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({token:$('adminKey').value})});V.authenticated=true;toast('Acceso habilitado');render()}catch(e){toast(e.message)}};connectSheetUI(status)}
async function connectSheetUI(adminAllowed){
  const put=async()=>{try{const q=await api('/api/sheets/status');if(!$('sheetProgress'))return;
    if(document.activeElement!==$('sheetID'))$('sheetID').value=q.spreadsheet_id||'';
    if(document.activeElement!==$('sheetInterval'))$('sheetInterval').value=q.interval_minutes||10;
    if(document.activeElement!==$('sheetFull'))$('sheetFull').value=q.full_every_hours||24;
    const stage=q.progress||{},on=q.enabled&&q.credential_configured;
    $('sheetLiveBadge').textContent=({SINCRONIZANDO:'SINCRONIZANDO',CONECTADO:'LECTURA CONFIRMADA',ERROR:'ERROR · RESPALDO LOCAL',PRECARGADOS:'DATOS PRECARGADOS'})[q.state]||'DATOS PRECARGADOS';
    $('sheetLiveBadge').className='chip '+(q.state==='CONECTADO'?'good':q.state==='ERROR'?'warn':'');
    $('sheetProgress').innerHTML=`<b>Último intento:</b> ${esc(q.last_attempt||'Sin ejecutar')} · <b>Última lectura exitosa:</b> ${esc(q.last_sync_at||'Sin ejecutar')} · <b>Estado:</b> ${esc(stage.phase||'pendiente')} ${stage.tab?'· '+esc(stage.tab):''} (${nfmt(stage.processed||0)}/${nfmt(stage.total||0)}) ${q.busy?'<span class="chip">Leyendo origen...</span>':''}<br><b>Última reconciliación completa:</b> ${esc(q.last_full_at||'Pendiente')} ${q.last_error?'<p class="warning-inline">'+esc(q.last_error)+'</p>':''}<br><b>Fuentes:</b> ${Object.entries(q.source_log||{}).map(([n,r])=>esc(n)+' '+nfmt(r.rows)).join(' · ')||'Sin sincronizar todavía'}`;
    for(const id of ['sheetIncremental','sheetFullSync'])if($(id))$(id).disabled=!adminAllowed||q.busy;
    if(q.last_sync_at&&V.lastSheetAt&&q.last_sync_at!==V.lastSheetAt){V.lastSheetAt=q.last_sync_at;toast('Google Sheets sincronizado. Recalculando indicadores…');refresh();}
  }catch(e){if($('sheetProgress'))$('sheetProgress').textContent=e.message}};
  if(adminAllowed){
    $('sheetSave').onclick=async()=>{try{const r=await api('/api/sheets/configure',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({spreadsheet_id:$('sheetID').value,credential_path:$('sheetKeyPath').value,interval_minutes:Number($('sheetInterval').value),full_every_hours:Number($('sheetFull').value),enabled:true})});toast('Conexión guardada. Pruebe el acceso y sincronice.');$('sheetKeyPath').value='';put()}catch(e){toast(e.message)}};
    $('sheetTest').onclick=async()=>{try{const r=await api('/api/sheets/test',{method:'POST'});toast(`Acceso correcto a ${r.title}. Pestañas: ${r.available.length}`);put()}catch(e){toast(e.message)}};
    for(const [id,full] of [['sheetIncremental',false],['sheetFullSync',true]])$(id).onclick=async()=>{try{await api('/api/sheets/sync',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({full})});toast('Se inició la sincronización; el progreso aparecerá aquí.');put()}catch(e){toast(e.message)}};
    $('sheetStop').onclick=async()=>{if(!confirm('¿Detener próximas sincronizaciones automáticas? Los datos locales se conservan.'))return;try{await api('/api/sheets/disable',{method:'POST'});toast('Sincronización desactivada');put()}catch(e){toast(e.message)}};
  }
  await put();if(V.page==='admin'){if(syncPoll)clearInterval(syncPoll);syncPoll=setInterval(()=>{if(V.page==='admin')put()},5500)}
}
async function analyzeFiles(){const files=V.dropFiles?.length?V.dropFiles:[...$('files').files];if(!files.length)return toast('Seleccione uno o más Excel/CSV');const out=$('preview');out.innerHTML='<p>Analizando encabezados, filas y claves de negocio…</p>';let reports=[];for(const file of files){try{const r=await api('/api/import/preview',{method:'POST',headers:{'x-file-name':encodeURIComponent(file.name),'x-sap-cut-date':$('sapCutDate')?.value||'','content-type':'application/octet-stream'},body:await file.arrayBuffer()});V.staged.push(r);reports.push(`<div class="stat-row"><div><label><input type="checkbox" class="import-select" checked value="${r.id}"> <strong>${esc(file.name)}</strong></label><small style="display:block">${r.records.map(x=>`${esc(x.type||'Desconocido')} · ${x.received} recibidas · ${x.stats?.added||0} nuevas · ${x.stats?.updated||0} actualizadas · ${x.stats?.duplicates||0} duplicadas · ${x.stats?.conflicts||0} conflictos`).join(' / ')}</small></div><span class="chip good">PREVIEW</span></div>`)}catch(e){reports.push(`<div class="stat-row">${esc(file.name)} <span class="chip bad">${esc(e.message)}</span></div>`)}}out.innerHTML=reports.join('')||'No se detectaron fuentes compatibles.';V.dropFiles=null}
async function applyFiles(){if(!V.staged.length)return toast('Primero debe ejecutar una previsualización.');const selected=[...document.querySelectorAll('.import-select:checked')].map(x=>x.value);if(!selected.length)return toast('Marque al menos un archivo en preview.');if(!confirm(`Aplicar ${selected.length} lote(s) al almacenamiento LOCAL? No se modificarán sistemas externos.`))return;try{const r=await api('/api/import/apply',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({ids:selected})});V.staged=[];toast('Datos aplicados: '+r.results.map(x=>`${x.type} +${x.added} / ${x.updated} actualizadas`).join(', '));await refresh();go('admin')}catch(e){toast(e.message)}}
document.addEventListener('DOMContentLoaded',()=>{init();setInterval(async()=>{try{const s=await api('/api/status');if(s.sheets?.last_sync_at&&V.lastSheetAt&&s.sheets.last_sync_at!==V.lastSheetAt){V.lastSheetAt=s.sheets.last_sync_at;await refresh();toast('Indicadores actualizados desde Google Sheets');}}catch{}},60000)});
